function normalize(lon){return ((lon+180)%360+360)%360-180}
function sampleRoute(points){const result=[points[0]];for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],steps=Math.max(2,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])*3));for(let j=1;j<=steps;j++)result.push([a[0]+(b[0]-a[0])*j/steps,a[1]+(b[1]-a[1])*j/steps]);}return result}
