const baseRadius=Math.max(55,Math.min(height/2-thickness-30,(width-2*margin-thickness-gap-labelWidth)/2));
const total=baseRadius*2+thickness+gap+labelWidth,cx=(width-total)/2+baseRadius,cy=height/2,radius=baseRadius*state.globe.zoom;
