function pauseRotation(){rotating=false;lastTime=0;syncPlayback()}
function focusCurrent(){pauseRotation();const c=byId[state.selected];if(!c)return;state[state.mode]={lon:c.center[0],lat:c.center[1],zoom:state.mode==='globe'?1.3:2.4};setupProjection();draw();save()}
