function setMode(m){if(!['globe','map'].includes(m)||state.page==='wind'||state.page==='regional')return;pauseRotation();state.mode=m;syncUI();setupProjection();draw();save()}
function setSeason(s,fromCycle=false){if(!M.seasons[s])return;const family=byId[state.selected]?.family;state.season=s;if(state.selected&&!activeCurrent(byId[state.selected]))state.selected=currents.find(c=>c.family===family&&c.season===s)?.id||null;if(!fromCycle)cycleElapsed=0;dirty=true;syncUI();draw();save()}
function setView(v){if(!['dynamic','static'].includes(v))return;state.view=v;if(v==='static')pauseAll();syncUI();save()}
function setPage(p,hash=true){if(!['wind','ocean','coupled','regional'].includes(p))return;pauseAll();state.page=p;if(p==='wind')state.mode='globe';if(p==='coupled'&&state.coupling==='enso')focusEnso();if(hash)history.replaceState(null,'','#'+p);dirty=true;syncUI();requestAnimationFrame(resize);save()}
function focusEnso(){rotating=false;state[state.mode]={lon:210,lat:0,zoom:state.mode==='map'?1.5:1};dirty=true;setupProjection();draw();save()}
function setEnsoPhase(id){if(!EnsoLab.phases[id])return;state.ensoPhase=id;if(id==='neutral')state.ensoCompare=false;dirty=true;syncUI();draw();save()}
function pauseAll(){playing=false;windPlaying=false;rotating=false;cycling=false;lastTime=0;cycleElapsed=0;syncPlayback();save();draw()}
function toggleFlow(kind){if(state.view==='static'||state.reducedMotion)return;if(kind==='wind'){if(!showWind()&&state.page!=='regional')return;windPlaying=!windPlaying}else if(kind==='ocean'){if(!showWater())return;playing=!playing}else return;lastTime=0;syncPlayback();draw()}
function togglePlay(){if(showWater())toggleFlow('ocean');else if(showWind()||state.page==='regional')toggleFlow('wind');else toast('請先開啟風場或洋流圖層。')}
function drop(){if(!state.selected||state.drifters.length>=8||!showWater())return;state.drifters.push({id:state.nextId++,current:state.selected,progress:0});if(state.view==='dynamic'&&!state.reducedMotion)playing=true;renderCurrent();syncPlayback();draw();save();toast(state.view==='static'||state.reducedMotion?'已放入起點；開啟動態並關閉減少動態後可播放。':'已放入漂流點，沿示意路徑前進。')}
function changeZoom(f){state[state.mode].zoom=Math.max(.8,Math.min(3,state[state.mode].zoom*f));setupProjection();draw();save()}
const pointers=new Map();let down=null,pinch=null,moved=false;
canvas.addEventListener('pointerdown',e=>{pauseRotation();canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1){down={x:e.clientX,y:e.clientY,...state[state.mode]};moved=false}else{const a=[...pointers.values()];pinch={distance:Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]),zoom:state[state.mode].zoom};moved=true}});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),p=[e.clientX-r.left,e.clientY-r.top];if(pointers.has(e.pointerId)){pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2&&pinch){const a=[...pointers.values()];state[state.mode].zoom=Math.max(.8,Math.min(3,pinch.zoom*Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1])/pinch.distance));setupProjection();draw();return}if(down){const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>4)moved=true;const f=state.mode==='globe'?100/projection.scale():180/(Math.PI*projection.scale());state[state.mode].lon=down.lon-dx*f;state[state.mode].lat=Math.max(-75,Math.min(75,down.lat+dy*f));setupProjection();draw()}$('hoverlabel').style.display='none';return}const windHit=windCellAt(p);if(windHit){canvas.style.cursor='pointer';const label=$('hoverlabel');label.textContent=M.cells[windHit.id].title;label.style.left=Math.min(width-100,p[0]+10)+'px';label.style.top=Math.max(5,p[1]-30)+'px';label.style.display='block';return}const hit=nearest(p);hovered=hit?.id;canvas.style.cursor=hit?'pointer':'grab';const label=$('hoverlabel');if(hit){label.textContent=byId[hit.id].name;label.style.left=Math.max(5,Math.min(width-180,p[0]+12))+'px';label.style.top=Math.max(5,p[1]-35)+'px';label.style.display='block'}else label.style.display='none'});
function release(e){const had=pointers.has(e.pointerId);pointers.delete(e.pointerId);if(e.type==='pointerup'&&had&&!moved&&down){const r=canvas.getBoundingClientRect(),hit=nearest([e.clientX-r.left,e.clientY-r.top]);const windHit=windCellAt([e.clientX-r.left,e.clientY-r.top]);if(windHit)chooseWindCell(windHit.id);else if(hit)selectCurrent(hit.id)}if(!pointers.size){down=null;pinch=null;save()}else {const p=[...pointers.values()][0];down={x:p[0],y:p[1],...state[state.mode]};pinch=null;moved=true}}
canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('pointerleave',()=>$('hoverlabel').style.display='none');
canvas.addEventListener('wheel',e=>{e.preventDefault();changeZoom(Math.exp(-e.deltaY*.001))},{passive:false});
canvas.addEventListener('keydown',e=>{const v=state[state.mode];if(e.key===' '){e.preventDefault();togglePlay();return}if(['+','=','-'].includes(e.key)){e.preventDefault();changeZoom(e.key==='-'?.9:1.1);return}const action={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,8],ArrowDown:[0,-8]}[e.key];if(action){e.preventDefault();pauseRotation();v.lon+=action[0];v.lat=Math.max(-75,Math.min(75,v.lat+action[1]));setupProjection();draw();save()}});

