function renderRegional(){const r=M.regions.find(r=>r.id===state.region);state.category=r.type;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===r.type)));$('regionChoices').innerHTML=M.regions.filter(x=>x.type===r.type).map(x=>'<button data-region="'+x.id+'" aria-pressed="'+(x.id===r.id)+'">'+x.name+'</button>').join('');document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>setRegion(b.dataset.region));if(!land)return;$('regionMap').innerHTML=cachedRegionMap(r,state.season,'main-');applyRegionTransform();if(state.view==='static'){if(regionCardsKey!==r.id){regionCardsKey=r.id;$('regionSeasonCards').innerHTML=M.order.map(s=>'<button data-region-season="'+s+'" class="region-season-card" aria-pressed="'+(s===state.season)+'"><span><strong>'+M.seasons[s].name+'</strong><small>'+M.seasons[s].months+'</small></span>'+cachedRegionMap(r,s,'mini-'+s)+'<p>'+M.regionInfo(r,s).title+'</p></button>').join('');document.querySelectorAll('[data-region-season]').forEach(b=>b.onclick=()=>{setSeason(b.dataset.regionSeason);$('regionControls').scrollIntoView({behavior:'smooth',block:'start'})});}document.querySelectorAll('[data-region-season]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.regionSeason===state.season)));}}
function setRegion(id){if(!M.regions.some(r=>r.id===id))return;state.region=id;regionZoom=1;regionPan=[0,0];syncUI();save()}
function applyRegionTransform(){$('regionMap').style.transform='translate('+regionPan[0]+'px,'+regionPan[1]+'px) scale('+regionZoom+')';}
function zoomRegion(f){regionZoom=Math.max(1,Math.min(3,regionZoom*f));if(regionZoom===1)regionPan=[0,0];applyRegionTransform();}
$('regionMapViewport').addEventListener('keydown',e=>{if(['+','=','-'].includes(e.key)){e.preventDefault();zoomRegion(e.key==='-'?.8:1.25)}else if(e.key==='Home'){e.preventDefault();regionZoom=1;regionPan=[0,0];applyRegionTransform()}else{const d={ArrowLeft:[25,0],ArrowRight:[-25,0],ArrowUp:[0,25],ArrowDown:[0,-25]}[e.key];if(d){e.preventDefault();regionPan=[regionPan[0]+d[0],regionPan[1]+d[1]];applyRegionTransform()}}});
let rp=null;
$('regionMapViewport').addEventListener('pointerdown',e=>{rp={x:e.clientX,y:e.clientY,pan:[...regionPan]};e.currentTarget.setPointerCapture(e.pointerId)});
$('regionMapViewport').addEventListener('pointermove',e=>{if(!rp)return;const maxX=$('regionMapViewport').clientWidth*(regionZoom-.3)/2,maxY=$('regionMapViewport').clientHeight*(regionZoom-.3)/2;regionPan=[Math.max(-maxX,Math.min(maxX,rp.pan[0]+e.clientX-rp.x)),Math.max(-maxY,Math.min(maxY,rp.pan[1]+e.clientY-rp.y))];applyRegionTransform()});
for(const evt of ['pointerup','pointercancel'])$('regionMapViewport').addEventListener(evt,()=>rp=null);
$('regionMapViewport').addEventListener('wheel',e=>{e.preventDefault();zoomRegion(Math.exp(-e.deltaY*.001))},{passive:false});
